// OCHO - Deal button.
// Object script on the Deal button; `refObject` is that ButtonObject.
//
// One press:
//   1. shuffles the deck standing in the Deck zone and waits for it to land,
//   2. deals one face-down card to each seated player, seven times around,
//   3. turns the next card face up in the DiscardPile zone.

const vars = declareVariables({
  deckZoneName: { type: "string", label: "Deck zone name", default: "Deck" },
  discardZoneName: { type: "string", label: "Discard zone name", default: "DiscardPile" },
  handSize: { type: "number", label: "Cards per player", default: 7, min: 1, max: 20 },
  dealPause: { type: "number", label: "Pause between cards (s)", default: 0.08, min: 0, max: 1 }
});

/** Clockwise seat order, matching the seat picker. */
const SEAT_ORDER = ["red", "blue", "green", "yellow", "purple", "orange", "pink", "cyan"];
/** How long to let the shuffle animation run before drawing from the deck. */
const SHUFFLE_SETTLE = 0.9;

/** One press at a time: a second press mid-deal would interleave two deals. */
let dealing = false;

/** The authored zone with this name, matched case-insensitively. Table zones have `seat === null`. */
async function findZone(name: string): Promise<SeatZoneInfo | null> {
  const wanted = name.trim().toLowerCase();
  if (!wanted) {
    return null;
  }
  const zones = await world.getSeatZones();
  for (const zone of zones) {
    if (zone.name.trim().toLowerCase() === wanted) {
      return zone;
    }
  }
  return null;
}

/**
 * Is this world point inside the zone box? Same XZ test the runtime uses: rotate the
 * offset by the negative yaw and compare against the box half-extents.
 */
function insideZone(zone: SeatZoneInfo, position: Vec3): boolean {
  const radians = (-zone.rotationY * Math.PI) / 180;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const dx = position[0] - zone.position[0];
  const dz = position[2] - zone.position[2];
  const localX = dx * cos - dz * sin;
  const localZ = dx * sin + dz * cos;
  return Math.abs(localX) <= zone.size[0] / 2 && Math.abs(localZ) <= zone.size[2] / 2;
}

/** A resting spot just inside the floor of a zone box, so a placed card settles in it. */
function restingPoint(zone: SeatZoneInfo): Vec3 {
  return [zone.position[0], zone.position[1] - zone.size[1] / 2 + 0.15, zone.position[2]];
}

/** The deck to deal from: the fullest one standing in the Deck zone, else the fullest anywhere. */
async function findDeck(deckZone: SeatZoneInfo | null): Promise<DeckObject | null> {
  const decks = await world.getAllObjects({ kind: "deck" });
  if (decks.length === 0) {
    return null;
  }
  const inZone = deckZone ? decks.filter((deck) => insideZone(deckZone, deck.position)) : [];
  const pool = inZone.length > 0 ? inZone : decks;
  let best: DeckObject | null = null;
  for (const deck of pool) {
    if (!best || deck.stackCount > best.stackCount) {
      best = deck;
    }
  }
  return best;
}

/** Seats that are occupied AND authored in this scene, clockwise from whoever pressed. */
function dealOrder(startSeat: string | null, seated: string[]): string[] {
  const ordered = SEAT_ORDER.filter((seat) => seated.indexOf(seat) !== -1);
  if (ordered.length === 0) {
    return [];
  }
  const startIndex = startSeat ? ordered.indexOf(startSeat) : -1;
  const offset = startIndex === -1 ? 0 : startIndex;
  const result: string[] = [];
  for (let step = 0; step < ordered.length; step += 1) {
    result.push(ordered[(offset + step) % ordered.length]);
  }
  return result;
}

refObject.onPressed.add(async (button, context) => {
  if (dealing) {
    world.log("Deal: a deal is already running.");
    return;
  }
  dealing = true;
  try {
    const discardZone = await findZone(vars.discardZoneName);
    if (!discardZone) {
      world.log(`Deal: no zone named "${vars.discardZoneName}" in this scene.`);
      return;
    }
    const deckZone = await findZone(vars.deckZoneName);
    const deck = await findDeck(deckZone);
    if (!deck) {
      world.log("Deal: no deck on the table.");
      return;
    }

    // Seats that are both authored with zones and occupied by a player.
    const zones = await world.getSeatZones();
    const seatsWithZones: string[] = [];
    for (const zone of zones) {
      if (zone.seat !== null && seatsWithZones.indexOf(zone.seat) === -1) {
        seatsWithZones.push(zone.seat);
      }
    }
    const players = world.getPlayers();
    const occupied: string[] = [];
    for (const player of players) {
      if (player.seat && occupied.indexOf(player.seat) === -1) {
        occupied.push(player.seat);
      }
    }
    const seated = seatsWithZones.filter((seat) => occupied.indexOf(seat) !== -1);

    // EventContext carries a peer id, not a seat, so map it: the deal starts with the
    // presser and moves clockwise. An unseated presser just starts at the head of the order.
    let startSeat: string | null = null;
    for (const player of players) {
      if (player.peerId === context.actor) {
        startSeat = player.seat;
      }
    }
    const order = dealOrder(startSeat, seated);
    if (order.length === 0) {
      world.log("Deal: nobody is seated.");
      return;
    }

    const handSize = Math.max(1, Math.round(vars.handSize));
    const pause = Math.max(0, vars.dealPause);

    deck.shuffle();
    await world.wait(SHUFFLE_SETTLE);

    // One card per player per lap, seven laps - not seven cards to one player at a time.
    for (let round = 0; round < handSize; round += 1) {
      for (const seat of order) {
        const dealt = await deck.dealTo({ seat, faceDown: true });
        if (!dealt) {
          world.log(`Deal: ran out of cards dealing to ${seat} on round ${round + 1}.`);
          return;
        }
        await world.wait(pause);
      }
    }

    // The starter card: the next one off the deck, face up in the discard zone.
    const starter = await deck.drawCard();
    if (!starter) {
      world.log("Deal: the deck ran out before the starter card.");
      return;
    }
    starter.setPosition(restingPoint(discardZone));
    await world.wait(0.15);
    if (starter.faceUp !== true) {
      starter.flip();
    }

    world.broadcast(`Dealt ${handSize} cards to ${order.length} player(s). Play begins.`);
  } finally {
    dealing = false;
  }
});

