// OCHO - Shuffle button (reshuffle the discards back into the draw pile).
// Object script on the Shuffle button; `refObject` is that ButtonObject.
//
// One press:
//   1. keeps the highest face-up card where it is, in the DiscardPile zone,
//   2. moves every other card out of that zone into the Deck zone, face down,
//   3. shuffles the deck.
//
// Anything already standing in the Deck zone is folded into the same pile, so a
// part-used draw pile is not left beside the reshuffled one.

const vars = declareVariables({
  deckZoneName: { type: "string", label: "Deck zone name", default: "Deck" },
  discardZoneName: { type: "string", label: "Discard zone name", default: "DiscardPile" }
});

/** Keys that must NOT ride along when a merged pile is rebuilt from a sample piece. */
const METADATA_SKIP = [
  "cards",
  "cardId",
  "scriptId",
  "scriptVars",
  "stackCount",
  "stackModelVersion",
  "cardOverlays",
  "counters",
  "__redacted"
];

let running = false;

async function findZone(name: string): Promise<SeatZoneInfo | null> {
  const wanted = name.trim().toLowerCase();
  if (!wanted) {
    return null;
  }
  const zones = await world.getSeatZones();
  for (const zone of zones) {
    if (zone.name.trim().toLowerCase() === wanted) {
      return zone;
    }
  }
  return null;
}

/** Same XZ containment test the runtime uses for seat zones. */
function insideZone(zone: SeatZoneInfo, position: Vec3): boolean {
  const radians = (-zone.rotationY * Math.PI) / 180;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const dx = position[0] - zone.position[0];
  const dz = position[2] - zone.position[2];
  const localX = dx * cos - dz * sin;
  const localZ = dx * sin + dz * cos;
  return Math.abs(localX) <= zone.size[0] / 2 && Math.abs(localZ) <= zone.size[2] / 2;
}

/** A resting spot just inside the floor of a zone box, so a placed piece settles in it. */
function restingPoint(zone: SeatZoneInfo): Vec3 {
  return [zone.position[0], zone.position[1] - zone.size[1] / 2 + 0.15, zone.position[2]];
}

/**
 * The card ids this piece holds, in pile order.
 *
 * Read off `metadata` rather than the typed `cards` accessor so one helper serves both a
 * pile and a loose card, and so a pile stored in either entry shape is understood.
 */
function cardIdsFrom(handle: ObjectHandle): string[] {
  if (handle.kind === "card") {
    const own = handle.metadata.cardId;
    return typeof own === "string" && own.length > 0 ? [own] : [];
  }
  const raw = handle.metadata.cards;
  if (!Array.isArray(raw)) {
    return [];
  }
  const ids: string[] = [];
  for (const entry of raw) {
    if (typeof entry === "string" && entry.length > 0) {
      ids.push(entry);
      continue;
    }
    if (entry && typeof entry === "object") {
      const record = entry as { cardId?: unknown; id?: unknown };
      const id = typeof record.cardId === "string"
        ? record.cardId
        : typeof record.id === "string" ? record.id : null;
      if (id) {
        ids.push(id);
      }
    }
  }
  return ids;
}

/** Metadata for a rebuilt pile: everything that describes the deck's art, nothing per-piece. */
function pileMetadata(template: ObjectHandle, cardIds: string[]): Record<string, unknown> {
  const built: Record<string, unknown> = {};
  for (const key of Object.keys(template.metadata)) {
    if (METADATA_SKIP.indexOf(key) === -1) {
      built[key] = template.metadata[key];
    }
  }
  built.cards = cardIds.map((cardId) => ({ cardId, faceDown: true }));
  return built;
}

/**
 * Fold every source piece into ONE face-down pile in `target`, and shuffle it.
 *
 * A single pile is simply moved, which keeps its id and everything authored on it. Several
 * pieces cannot be merged in place - a table script has no "combine" verb - so they are
 * rebuilt as one new pile carrying the sample piece's deck metadata, and the originals go.
 */
async function gatherInto(sources: ObjectHandle[], target: SeatZoneInfo): Promise<boolean> {
  if (sources.length === 0) {
    return false;
  }

  if (sources.length === 1 && sources[0].kind === "deck") {
    const only = sources[0];
    only.setPosition(restingPoint(target));
    await world.wait(0.2);
    if (only.faceUp === true) {
      only.flip();
      await world.wait(0.2);
    }
    only.shuffle();
    return true;
  }

  const cardIds: string[] = [];
  let template: ObjectHandle | null = null;
  for (const source of sources) {
    const ids = cardIdsFrom(source);
    for (const id of ids) {
      cardIds.push(id);
    }
    // Prefer a pile as the sample: it carries the deck-level art slice in full.
    if (ids.length > 0 && (!template || (template.kind !== "deck" && source.kind === "deck"))) {
      template = source;
    }
  }
  if (!template || cardIds.length === 0) {
    world.log("Reshuffle: nothing recognisable as cards to gather.");
    return false;
  }

  const label = template.kind === "deck" && template.name ? template.name : "Deck";
  const tags = template.tags.slice();
  const metadata = pileMetadata(template, cardIds);

  for (const source of sources) {
    source.destroy();
  }
  await world.wait(0.3);

  const rebuilt = await world.spawnObject({
    kind: "deck",
    name: label,
    position: restingPoint(target),
    metadata,
    tags
  });
  if (!rebuilt) {
    world.log("Reshuffle: could not rebuild the draw pile.");
    return false;
  }
  await world.wait(0.3);
  rebuilt.shuffle();
  return true;
}

refObject.onPressed.add(async () => {
  if (running) {
    world.log("Reshuffle: already running.");
    return;
  }
  running = true;
  try {
    const discardZone = await findZone(vars.discardZoneName);
    const deckZone = await findZone(vars.deckZoneName);
    if (!discardZone || !deckZone) {
      world.log(`Reshuffle: need zones named "${vars.discardZoneName}" and "${vars.deckZoneName}".`);
      return;
    }

    const allDecks = await world.getAllObjects({ kind: "deck" });
    const allCards = await world.getAllObjects({ kind: "card" });
    const discardPiles = allDecks.filter((deck) => insideZone(discardZone, deck.position));
    const discardCards = allCards.filter((card) => insideZone(discardZone, card.position));
    const inDiscard: ObjectHandle[] = (discardPiles as ObjectHandle[]).concat(discardCards);
    if (inDiscard.length === 0) {
      world.log("Reshuffle: the discard zone is empty.");
      return;
    }

    // Highest piece wins: that is the face-up card play is currently matching against.
    let highest: ObjectHandle = inDiscard[0];
    for (const piece of inDiscard) {
      if (piece.position[1] > highest.position[1]) {
        highest = piece;
      }
    }

    // Peel the played card off the pile so it stays behind while the rest goes back.
    let keeperId = highest.id;
    if (highest.kind === "deck" && highest.stackCount > 1) {
      const peeled = await (highest as DeckObject).drawCard();
      if (peeled) {
        keeperId = peeled.id;
        peeled.setPosition(restingPoint(discardZone));
        await world.wait(0.2);
        if (peeled.faceUp !== true) {
          peeled.flip();
        }
      }
    } else if (highest.faceUp !== true) {
      highest.flip();
    }

    // Everything else in the discard zone, plus whatever is already standing in the deck
    // zone, becomes the new draw pile. Re-read each piece: the peel above changed one.
    const sources: ObjectHandle[] = [];
    for (const piece of inDiscard) {
      if (piece.id === keeperId) {
        continue;
      }
      const state = await piece.refresh();
      if (state) {
        sources.push(piece);
      }
    }
    for (const deck of allDecks) {
      if (deck.id !== keeperId && insideZone(deckZone, deck.position)) {
        const state = await deck.refresh();
        if (state) {
          sources.push(deck);
        }
      }
    }
    for (const card of allCards) {
      if (card.id !== keeperId && insideZone(deckZone, card.position)) {
        const state = await card.refresh();
        if (state) {
          sources.push(card);
        }
      }
    }

    if (sources.length === 0) {
      world.log("Reshuffle: only the played card is in the discard zone - nothing to gather.");
      return;
    }

    const gathered = await gatherInto(sources, deckZone);
    if (gathered) {
      world.broadcast("Discards reshuffled into the draw pile.");
    }
  } finally {
    running = false;
  }
});

